/**
 * Place a pre-compiled module (see `native.ts`, generated by tools/aspect/gen_native.py) at its
 * real address. The arithmetic is the same as in that generator, where it is tested against lld.
 */
import { FirmwareError } from '../types';
import type { FirmwareTarget } from '../target';
import { NATIVE } from './native';
import type { NativeModule } from './native';

export interface LinkedModule {
  code: Uint8Array;
  /** Absolute addresses of the module's exported functions. */
  symbols: Record<string, number>;
}

/**
 * Firmware addresses the modules call directly (compiled in as MOVW/MOVT pairs, not bound): 1.11
 * address and how often it occurs. For another firmware they are replaced by its addresses.
 */
export const FIXED_ADDRESSES: Readonly<Record<string, readonly (readonly [number, number])[]>> = {
  state: [[0x5323f018, 2]], // the current UserData (CURRENT in crop_state.c)
  identity: [[0x536c79cc, 1]], // the size classification of a photo (crop_image_source_aspect)
  map: [],
};

export function linkNative(name: keyof typeof NATIVE, count: number, origin: number, bindings: Readonly<Record<string, number>>, target?: FirmwareTarget): LinkedModule {
  const linked = linkModule(NATIVE[name], name, count, origin, bindings);
  if (target && target.id !== '1.11') portFixed(linked.code, FIXED_ADDRESSES[name], target);
  return linked;
}

/** Replace the MOVW/MOVT pairs that load `fixed` 1.11 addresses by the target's addresses. */
function portFixed(code: Uint8Array, fixed: readonly (readonly [number, number])[], target: FirmwareTarget): void {
  const dv = new DataView(code.buffer, code.byteOffset, code.byteLength);
  const n = code.length / 4;
  for (const [address, times] of fixed) {
    let found = 0;
    for (let i = 0; i < n; i++) {
      const w = dv.getUint32(i * 4, true);
      if ((w & 0x0ff00000) !== 0x03000000 || (((w >>> 4) & 0xf000) | (w & 0xfff)) !== (address & 0xffff)) continue;
      const rd = (w >>> 12) & 15;
      for (let k = i + 1; k < Math.min(n, i + 9); k++) {
        const w2 = dv.getUint32(k * 4, true);
        if ((w2 & 0x0ff00000) !== 0x03400000 || ((w2 >>> 12) & 15) !== rd) continue;
        if ((((w2 >>> 4) & 0xf000) | (w2 & 0xfff)) !== address >>> 16) break;
        const to = target.va(address);
        dv.setUint32(i * 4, ((w & 0xfff0f000) | ((to & 0xf000) << 4) | (to & 0xfff)) >>> 0, true);
        dv.setUint32(k * 4, ((w2 & 0xfff0f000) | (((to >>> 16) & 0xf000) << 4) | ((to >>> 16) & 0xfff)) >>> 0, true);
        found++;
        break;
      }
    }
    if (found !== times) throw new FirmwareError('internal', `module address 0x${address.toString(16)} found ${found} times, expected ${times}`);
  }
}

/** `linkNative` for any pre-compiled module (e.g. `slotparams-native.ts`). */
export function linkModule(mod: NativeModule, name: string, count: number, origin: number, bindings: Readonly<Record<string, number>>): LinkedModule {
  const variant = mod.variants[count];
  if (!variant) throw new FirmwareError('too-many-ratios', `no ${name} module for a count of ${count}`);
  if (origin % 4 !== 0) throw new FirmwareError('internal', 'unaligned module address');
  const values = mod.bindings.map((b) => {
    const v = bindings[b];
    if (v === undefined) throw new FirmwareError('internal', `unbound symbol ${b}`);
    return v >>> 0;
  });
  if (Object.keys(bindings).length !== mod.bindings.length) throw new FirmwareError('internal', `unexpected symbols for ${name}`);
  const raw = Uint8Array.from(atob(variant.code), (c) => c.charCodeAt(0));
  if (raw.length % 4 !== 0) throw new FirmwareError('internal', 'module length');
  const code = raw.slice();
  const dv = new DataView(code.buffer);
  for (const [offset, kind, where, index, addend] of variant.relocs) {
    const symbol = where === 'x' ? values[index] : origin + index;
    const value = (symbol + addend) >>> 0;
    let word = dv.getUint32(offset, true);
    if (kind === 'w' || kind === 't') {
      const imm = kind === 'w' ? value & 0xffff : value >>> 16;
      word = ((word & 0xfff0f000) | ((imm & 0xf000) << 4) | (imm & 0xfff)) >>> 0;
    } else {
      // A call or jump into the firmware lands exactly on the bound function. (A module whose
      // branches were recorded 8 bytes before their targets, as a fork's 7..12-slot variants built
      // with another toolchain were, called __stack_chk_fail at every start and hung the camera.)
      if (where === 'x' && addend !== 0) throw new FirmwareError('internal', `${name}: a branch to ${mod.bindings[index]} does not land on it`);
      const delta = value - (origin + offset + 8);
      if (delta % 4 !== 0 || !(delta >= -(1 << 25) && delta < 1 << 25)) throw new FirmwareError('internal', 'module branch out of range');
      word = ((word & 0xff000000) | ((delta >> 2) & 0xffffff)) >>> 0;
    }
    dv.setUint32(offset, word, true);
  }
  const symbols: Record<string, number> = {};
  for (const k of Object.keys(variant.exports)) symbols[k] = origin + variant.exports[k];
  return { code, symbols };
}
